import re, sys, glob

def strip_comments(text):
    # strip block comments /- ... -/ (handle nesting)
    out = []
    i = 0
    depth = 0
    n = len(text)
    while i < n:
        if text[i:i+2] == '/-':
            depth += 1
            i += 2
            while i < n and depth > 0:
                if text[i:i+2] == '/-':
                    depth += 1
                    i += 2
                elif text[i:i+2] == '-/':
                    depth -= 1
                    i += 2
                else:
                    if text[i] == '\n':
                        out.append('\n')
                    i += 1
            continue
        if text[i:i+2] == '--':
            # line comment - skip to end of line
            j = text.find('\n', i)
            if j == -1:
                i = n
            else:
                out.append('\n')
                i = j+1
            continue
        out.append(text[i])
        i += 1
    return ''.join(out)

def split_decls(text):
    # naive split: a new top-level decl starts at a line beginning with
    # (optional attribute lines, then) def/theorem/lemma/instance/abbrev/structure/class
    # We'll scan lines, and group lines into declaration blocks starting
    # at lines matching decl keyword at col 0 (not indented), stopping
    # at the next such line.
    lines = text.split('\n')
    starts = []
    kw_re = re.compile(r'^(private\s+|protected\s+|noncomputable\s+|scoped\s+)*'
                        r'(def|theorem|lemma|instance|abbrev|structure|class|example)\b')
    for idx, line in enumerate(lines):
        if kw_re.match(line):
            starts.append(idx)
    blocks = []
    for k, s in enumerate(starts):
        e = starts[k+1] if k+1 < len(starts) else len(lines)
        blocks.append('\n'.join(lines[s:e]))
    return blocks

def signature_part(block):
    # signature is up to first ':=' or ' where' (top-level, not inside brackets/parens)
    depth = 0
    i = 0
    n = len(block)
    while i < n:
        c = block[i]
        if c in '([{':
            depth += 1
        elif c in ')]}':
            depth -= 1
        elif depth == 0:
            if block[i:i+2] == ':=':
                return block[:i]
            if block[i:i+6] == ' where' and (i+6==n or not block[i+6].isalnum()):
                return block[:i]
        i += 1
    return block

def count_binder_class(files, classname):
    total = 0
    per_file = {}
    pat = re.compile(r'\[[^\[\]]*\b' + re.escape(classname) + r'\b[^\[\]]*\]')
    for f in files:
        text = open(f, encoding='utf-8').read()
        stripped = strip_comments(text)
        blocks = split_decls(stripped)
        cnt = 0
        for b in blocks:
            sig = signature_part(b)
            if pat.search(sig):
                cnt += 1
        if cnt:
            per_file[f] = cnt
        total += cnt
    return total, per_file

